"Общий разговор Ловчих.":"사냥꾼들의 자유 대화방이에요.",
"Торговля: договаривайтесь о сделках — сами сделки идут через Аукцион.":"거래: 거래 약속을 잡는 곳이에요. 실제 거래는 경매장에서 해요.",
"Ищите команду для Разломов: пишите код комнаты и место.":"균열 팀을 찾아보세요: 방 코드와 장소를 적어 주세요.",
"Вопросы новичков и советы бывалых.":"신입의 질문과 베테랑의 조언.",
"Канал твоей дружины — его видят только свои.":"우리 클랜 채널이에요. 클랜원만 볼 수 있어요.",
"Сегодня":"오늘",
"Вчера":"어제",
"Ссылки запрещены, грубость скрывается.":"링크는 금지되고, 욕설은 가려져요.",
"Правила чата":"채팅 규칙",
"Скрытых Ловчих: {0} · Вернуть":"숨긴 사냥꾼: {0} · 되돌리기",
"Здесь пока тихо":"아직 조용해요",
"Напиши первым — тебя увидят все Ловчие твоей дружины.":"먼저 말을 걸어 보세요. 클랜의 모든 사냥꾼이 볼 수 있어요.",
"Напиши первым — тебя увидят все Ловчие Ордена.":"먼저 말을 걸어 보세요. 기사단의 모든 사냥꾼이 볼 수 있어요.",
"Новые сообщения: {0}":"새 메시지: {0}",
"Пожаловаться?":"신고할까요?",
"На сообщение Ловчего «{0}». После трёх жалоб от разных Ловчих оно скрывается для всех.":"사냥꾼 ‘{0}’의 메시지를 신고해요. 서로 다른 사냥꾼 셋이 신고하면 모두에게서 숨겨져요.",
"Пожаловаться":"신고",
"Жалоба отправлена — спасибо":"신고했어요. 고마워요",
"Скрыть сообщения?":"메시지를 숨길까요?",
"Сообщения Ловчего «{0}» перестанут показываться на этом телефоне. Вернуть можно в любой момент — строкой «Скрытых Ловчих» вверху чата.":"사냥꾼 ‘{0}’의 메시지가 이 휴대폰에서 더 이상 보이지 않아요. 채팅 위쪽의 ‘숨긴 사냥꾼’에서 언제든 되돌릴 수 있어요.",
"Скрыть":"숨기기",
"Скрыто. Вернуть — «Скрытых Ловчих» вверху чата":"숨겼어요. 채팅 위쪽 ‘숨긴 사냥꾼’에서 되돌릴 수 있어요",
"Дружину можно выбрать с {0} уровня":"클랜은 레벨 {0}부터 고를 수 있어요",
"Выбери дружину":"클랜 선택",
"Дружины Ордена держат Капища: поставь своего духа защитником — и Капище окрасится цветом твоей дружины, а тебе каждый день будет приходить дань. Выбор — навсегда.":"기사단의 클랜들은 카피셰를 지켜요. 내 정령을 방어자로 세우면 카피셰가 우리 클랜 색으로 물들고, 매일 공물이 들어와요. 한 번 고르면 바꿀 수 없어요.",
"Позже":"나중에",
"Вступить в «{0}»? Сменить дружину потом нельзя.":"‘{0}’에 가입할까요? 나중에 클랜을 바꿀 수 없어요.",
"Вступить":"가입",
"Ты в «{0}»! Побеждай на Капищах и ставь защитников.":"‘{0}’에 가입했어요! 카피셰에서 이기고 방어자를 세우세요.",
"Кого поставить защитником?":"누구를 방어자로 세울까요?",
"Дух останется у тебя: на Капище встанет его отражение. Пока он стоит, раз в день приходит дань — ✦ {0} и оберег.":"정령은 그대로 내 곁에 있고, 카피셰에는 그 그림자가 서요. 서 있는 동안 하루에 한 번 공물이 들어와요: ✦ {0}, 부적 1개.",
"Отражение стоит до {0} суток: первые {1} ч в полной силе, потом устаёт и слабеет, а затем возвращается домой. Защитники — не больше чем на {2} Капищах.":"그림자는 최대 {0}일 동안 서 있어요: 처음 {1}시간은 최상의 상태이고, 그다음엔 지쳐서 약해지다가 집으로 돌아와요. 방어자는 최대 {2}곳의 카피셰에만 세울 수 있어요.",
"Защитник встал на Капище «{0}» — оно под знаменем «{1}»":"방어자가 카피셰 ‘{0}’에 섰어요. 이제 ‘{1}’의 깃발 아래 있어요",
"Срок на посту вышел — защитники вернулись с {0}. За службу: {1}":"근무 기간이 끝나 방어자들이 {0}에서 돌아왔어요. 근무 보상: {1}",
"Защитники вернулись с {0}: соперники победили. За службу: {1}":"상대가 이겨서 방어자들이 {0}에서 돌아왔어요. 근무 보상: {1}",
"Защитник вернулся с {0}: соперники победили. За службу: {1}":"상대가 이겨서 방어자가 {0}에서 돌아왔어요. 근무 보상: {1}",
"Дружина":"클랜",
