"меньше часа":"1시간 미만",
"{0} ч":"{0}시간",
"на посту {0} · защитников {1} из {2}":"근무 {0} · 방어자 {1}/{2}",
"устал: уровень −{0}% · домой через {1} ч":"지침: 레벨 −{0}% · {1}시간 뒤 귀환",
"в полной силе ещё {0} ч":"{0}시간 더 최상의 상태",
"Капища рядом (≈5 км)":"근처 카피셰 (≈5km)",
"Капища по всей России":"전국의 카피셰",
"Мои защитники":"내 방어자",
"{0} из {1}":"{0}/{1}",
"Пока нигде. Победи на Капище и поставь защитника — каждый день будет приходить дань.":"아직 없어요. 카피셰에서 이기고 방어자를 세우면 매일 공물이 들어와요.",
"Дань — ✦ {0}, оберег и {1} {2} в день за каждое Капище, где твой защитник отстоял хотя бы {3} ч. Защитник стоит до {4} суток и понемногу устаёт; если соперники его победят или срок выйдет, он вернётся с искрами за время на посту. Часть Капищ — вольные: их не держит ни одна дружина.":"공물: 방어자가 최소 {3}시간 지킨 카피셰마다 하루 ✦ {0}, 부적 1개, {2} {1}개. 방어자는 최대 {4}일 동안 서 있으며 조금씩 지쳐요. 상대에게 지거나 기간이 끝나면 근무한 시간만큼 불꽃을 들고 돌아와요. 일부 카피셰는 자유 카피셰라 어느 클랜도 차지할 수 없어요.",
"Следопыт ведёт к Капищу «{0}»":"추적자가 카피셰 ‘{0}’(으)로 안내해요",
