"восточнее 105° в. д.":"동경 105° 동쪽",
"Запад":"서부",
"до 40° в. д.":"동경 40°까지",
"Центр":"중부",
"40–90° в. д.":"동경 40–90°",
"Восток":"동부",
"от 90° в. д.":"동경 90°부터",
"Оберег":"부적",
"Узелок с заговорённой травой. Бросай в духа, чтобы поймать.":"주문을 건 약초 꾸러미. 정령에게 던져서 잡으세요.",
"Серебряный оберег":"은 부적",
"Серебро держит духов крепче. Шанс поимки ×1,5.":"은은 정령을 더 단단히 붙잡아요. 포획 확률 ×1.5.",
"Золотой оберег":"금 부적",
"Лучший оберег Ордена. Шанс поимки ×2.":"기사단 최고의 부적. 포획 확률 ×2.",
"Духи обожают мёд. Успокаивает духа: шанс поимки ×1,5 на один бросок.":"정령들은 꿀을 정말 좋아해요. 정령을 진정시켜요: 한 번 던질 때 포획 확률 ×1.5.",
"Подорожник":"질경이",
"Лист к ране — и полегчало. Возвращает духу четверть здоровья.":"상처에 잎을 대면 한결 나아져요. 정령의 체력을 4분의 1 회복해요.",
"Целебный отвар":"치유 탕약",
"Травы Велеса, сваренные в родниковой воде. Возвращает духу 60% здоровья.":"샘물에 달인 벨레스의 약초. 정령의 체력을 60% 회복해요.",
"Мёртвая вода":"묘르트바야 보다",
"Редкая сказочная вода, что сращивает самые тяжкие раны. Дух без сил поднимется на 4 часа раньше. Живых не лечит.":"가장 깊은 상처도 아물게 하는 희귀한 옛이야기 속의 물. 기절한 정령이 4시간 일찍 일어나요. 기절하지 않은 정령은 치료하지 못해요.",
"Живая вода":"지바야 보다",
"Возвращает духу половину здоровья, а в разломе — лечит прямо в бою. Духа без сил не поднимет.":"정령의 체력을 절반 회복해요. 균열에서는 전투 중에 바로 치료해요. 기절한 정령은 일으키지 못해요.",
"Ладан":"향",
"Дымок приманивает духов: 30 минут их вокруг вдвое больше.":"연기가 정령을 불러 모아요: 30분 동안 주변 정령이 두 배로 늘어요.",
"Дальний пропуск":"원거리 패스",
"Грамота Ордена: закрыть Разлом до 5 км от тебя, не подходя к нему. Один Орден дарит каждый день.":"기사단 증서: 5km 안의 균열을 가까이 가지 않고도 닫을 수 있어요. 기사단이 매일 하나씩 선물해요.",
"Настой опыта":"경험치 물약",
"Медовый настой на травах Велеса: сутки опыта на четверть больше.":"벨레스의 약초로 달인 꿀 물약: 24시간 동안 경험치가 25% 더 늘어요.",
"Подарок":"선물",
"Узелок для друга: обереги, мёд, иногда кокон. Отправляется в «Меню → Друзья», раз в день каждому.":"친구에게 보내는 꾸러미: 부적, 꿀, 가끔 고치도. ‘메뉴 → 친구’에서 친구마다 하루에 한 번 보낼 수 있어요.",
"Знакомый":"아는 사이",
"Приятель":"친한 사이",
"Друг":"친구",
