"Победи хранителя капища":"카피셰 수호자 이기기",
"Выведи духа из кокона":"고치에서 정령 부화시키기",
"Освободи родник от прислужников Нави":"나브의 하수인에게서 샘 되찾기",
"2031 год. Геомагнитная буря, которую потом назовут <b>Тонкой ночью</b>, истончила границу между Явью — нашим миром — и Навью, миром духов.":"2031년. 훗날 <b>얇은 밤</b>이라 불리게 될 지자기 폭풍이 우리의 세상 야브와 정령의 세상 나브 사이의 경계를 얇게 만들었어요.",
"Теперь по улицам бродят духи. Древние — Леший, Водяной, Домовой. И новые, рождённые городом: Вайфайка, Трамвайник, Фонарник.":"이제 거리에는 정령들이 돌아다녀요. 레시, 보댜노이, 도모보이 같은 오래된 정령들. 그리고 도시가 낳은 새로운 정령들: 바이파이카, 트람바이니크, 포나르니크.",
"Древний <b>Орден Оберега</b> снова набирает Ловчих. Твоя задача — находить духов, ловить их оберегами, черпать силу из родников и закрывать разломы, откуда лезет всё самое опасное.":"오래된 <b>부적 기사단</b>이 다시 사냥꾼을 모집해요. 할 일은 정령을 찾아 부적으로 잡고, 샘에서 힘을 얻고, 가장 위험한 것들이 기어 나오는 균열을 닫는 거예요.",
"Ясно":"맑음",
"Переменная облачность":"구름 조금",
"Пасмурно":"흐림",
"Туман":"안개",
"Дождь":"비",
"Снег":"눈",
