"Ветрено":"바람",
"Полнолуние":"보름달",
"Ночью духи Тени и Воды встречаются чаще, а Русалки и Навки выходят к людям.":"밤에 그림자와 물 정령이 더 자주 나타나고, 루살카와 나프카가 사람들 곁으로 나와요.",
"Новолуние":"신월",
"В безлунную ночь сияющие духи встречаются вдвое чаще.":"달 없는 밤에는 빛나는 정령이 두 배로 자주 나타나요.",
