"Бой через":"전투 시작까지",
"Соперник — живой Ловчий. Тапай — быстрая атака, она копит энергию; полная шкала — «Приём». Щиты берегут от его приёмов.":"상대는 실제 사냥꾼이에요. 탭하면 빠른 공격, 에너지가 차요. 게이지가 가득 차면 ‘기술’. 방패는 상대의 기술을 막아 줘요.",
"Нет связи с сервером — переподключаюсь…":"서버와 연결이 끊겼어요 — 다시 연결하는 중…",
"Приём сейчас не выйдет":"지금은 기술을 쓸 수 없어요",
