"Бой будет проигран, рейтинг уменьшится, опыта не будет.":"전투에서 패배하고, 레이팅이 내려가며, 경험치는 없어요.",
"Все духи {0} без сил.":"{0}의 정령이 모두 기절했어요.",
"Все твои духи без сил.":"내 정령이 모두 기절했어요.",
"Время вышло — силы равны.":"시간 종료 — 남은 힘이 같아요.",
"Время вышло — у твоих духов осталось больше сил.":"시간 종료 — 내 정령들의 힘이 더 남았어요.",
"Время вышло — у духов {0} осталось больше сил.":"시간 종료 — {0}의 정령들의 힘이 더 남았어요.",
