"Команда на бой":"출전 팀",
"Соперник — живой Ловчий: ищу {0}. Рейтинг зависит от силы соперника · опыт — за первые {1} боёв дня":"상대는 실제 사냥꾼: {0} 찾는 중. 레이팅은 상대의 실력에 따라 달라요 · 경험치는 그날 처음 {1}판까지",
"Общая таблица всех Ловчих появится, когда к игре подключат облачный сервер.":"모든 사냥꾼의 순위표는 게임에 클라우드 서버가 연결되면 나타나요.",
"Обновляется в реальном времени":"실시간 업데이트",
"Ловчих":"사냥꾼",
"{0} {1} в сезоне":"이번 시즌 {1} {0}명",
"Загружаю таблицу…":"순위표를 불러오는 중…",
"Таблица недоступна: {0}":"순위표를 볼 수 없어요: {0}",
"В этом сезоне ещё никто не сыграл в Лиге — будь первым!":"이번 시즌엔 아직 리그에서 싸운 사람이 없어요 — 첫 번째가 되어 보세요!",
"{0}-е место":"{0}위",
"Ты":"나",
"Лучшие в лиге «{0}»":"‘{0}’ 리그 상위권",
"Топ-50 сезона":"시즌 TOP 50",
"Тебя нет в таблице: так выбрано в Настройках.":"설정에 따라 순위표에 표시되지 않아요.",
"Нажми на Ловчего, чтобы открыть его карточку.":"사냥꾼을 누르면 카드를 볼 수 있어요.",
"ты здесь":"현재 위치",
"от {0}":"{0}부터",
"начало пути":"여정의 시작",
"Получено в этом сезоне":"이번 시즌에 받음",
"Рейтинг зависит от соперника: победа над сильным даёт много, над слабым — мало; поражение от слабого стоит дороже. В твоей лиге победа над равным — +{0}, поражение — −{1}; чем выше лига, тем медленнее подъём. Из лиги можно выпасть. Награду за лигу дают один раз за сезон. В начале нового сезона рейтинг сверх {2} срезается наполовину, а за высшую лигу прошлого сезона Орден дарит сундук. В лигах «{3}», «{4}» и «{5}» — ещё и амулет.":"레이팅은 상대에 따라 달라요: 강한 상대를 이기면 많이, 약한 상대를 이기면 조금 오르고, 약한 상대에게 지면 더 많이 잃어요. 내 리그에서 비슷한 상대를 이기면 +{0}, 지면 −{1}이고, 리그가 높을수록 천천히 올라요. 리그에서 떨어질 수도 있어요. 리그 보상은 시즌마다 한 번만 받아요. 새 시즌이 시작되면 {2}을(를) 넘는 레이팅이 절반으로 줄고, 지난 시즌 최고 리그에 따라 기사단이 상자를 선물해요. ‘{3}’, ‘{4}’, ‘{5}’ 리그에서는 아뮬렛도 받아요.",
"<b>{0}-е место</b> из {1} в сезоне":"시즌 {1}명 중 <b>{0}위</b>",
"Тебя нет в таблице (Настройки)":"순위표에 표시 안 함 (설정)",
"Сыграй бой, чтобы попасть в таблицу":"한 판 싸우면 순위표에 올라요",
"Карточка откроется после обновления сервера":"서버가 업데이트되면 카드를 볼 수 있어요",
"Неизвестный ход":"알 수 없는 행동",
"Слишком много ударов сразу":"공격이 한꺼번에 너무 많아요",
"Неизвестный приём":"알 수 없는 기술",
"Этот приём не выучен":"배우지 않은 기술이에요",
"Неверный приём":"잘못된 기술",
"Этого духа не выпустить":"이 정령은 내보낼 수 없어요",
"Бросай оберег, когда кольцо сжимается: «Отлично!» даёт больше опыта и шанс поимки.":"링이 줄어들 때 부적을 던지세요. ‘훌륭해요!’가 뜨면 경험치와 포획 확률이 올라가요.",
"Родники наполняются снова через несколько минут — прогулка по кругу приносит припасы.":"샘은 몇 분 뒤 다시 차올라요. 한 바퀴 산책하면 물자가 쌓여요.",
"Спутник ходит с тобой и находит эссенцию своего семейства.":"파트너는 함께 걸으며 자기 계열의 정수를 찾아 줘요.",
"В Лиге дерутся живые Ловчие: победа над сильным соперником даёт больше рейтинга, чем над слабым.":"리그에서는 실제 사냥꾼끼리 싸워요: 강한 상대를 이기면 약한 상대보다 레이팅이 더 올라요.",
"Разломы открываются у Капищ каждый час: собери команду из трёх духов.":"균열은 매시간 카피셰 곁에 열려요. 정령 셋으로 팀을 꾸리세요.",
