"GPS неточный (±{0} м). Выйди на открытое место и подожди.":"GPS가 정확하지 않아요 (±{0}m). 탁 트인 곳에서 잠시 기다려 주세요.",
"Новое место":"새 장소",
"Название":"이름",
"Например: Памятник Пушкину":"예: 푸시킨 동상",
