"Что здесь будет":"여기에 생길 것",
"Родник — для любого интересного объекта. Капище — для заметных мест: памятник, парк, крупное здание.":"샘은 흥미로운 대상이면 무엇이든 괜찮아요. 카피셰는 눈에 띄는 장소용이에요: 기념비, 공원, 큰 건물.",
"Точка объекта":"대상 위치",
"Круг — {0} м от места съёмки (±{1} м). Перетащи булавку точно на объект.":"원은 촬영 지점에서 {0}m 범위예요 (±{1}m). 핀을 대상 위로 정확히 옮기세요.",
"Отправить на проверку":"검토 요청 보내기",
