"Великий разлом":"대균열",
"Разломы открываются с {0} уровня Ловчего":"균열은 사냥꾼 Lv.{0}부터 열려요",
"Дальний бой · пропусков: {0}":"원거리 전투 · 패스: {0}",
"Нужен Дальний пропуск — в Лавку":"원거리 패스 필요 — 상점으로",
"Разлом открылся у «{0}»":"‘{0}’ 곁에 균열이 열렸어요",
"Сила босса ≈ {0} · закроется через {1}":"보스 전투력 ≈ {0} · {1} 후 닫혀요",
"Слабость: {0}":"약점: {0}",
"Великий разлом в одиночку по силам немногим — позови друзей: втроём его закрыть куда легче.":"대균열은 혼자 이기기 어려워요 — 친구를 부르세요: 셋이면 훨씬 쉽게 닫을 수 있어요.",
"{0}: урон +20% у {1}":"{0}: {1} 피해 +20%",
"Этот разлом ты уже закрыл. Новый босс — в начале следующего часа.":"이 균열은 이미 닫았어요. 새 보스는 다음 정각에 나타나요.",
"Разломов закрыто":"닫은 균열",
"До Разлома {0}. Дальний пропуск: один Орден дарит каждый день, ещё — в Лавке. Позвать друзей можно, только подойдя к Капищу.":"균열까지 {0}. 원거리 패스: 기사단이 매일 하나씩 주고, 상점에서도 살 수 있어요. 친구를 부르려면 카피셰 가까이 가야 해요.",
"Позвать друзей — совместный бой":"친구 부르기 — 협동 전투",
"Разлом схлопнулся — его час прошёл. Новые открываются в начале каждого часа.":"균열이 닫혔어요. 시간이 다 됐어요. 새 균열은 매시 정각에 열려요.",
"Ищу Разломы у Капищ вокруг…":"주변 카피셰의 균열을 찾는 중…",
"Жду, когда найдётся твоё место на карте…":"지도에서 내 위치를 찾는 중…",
"Пропусков: {0}":"패스: {0}",
"новые через {0}":"{0} 후 새로 지급",
"закрыт":"닫음",
"рядом":"근처",
"Сейчас вокруг нет открытых Разломов. Новые открываются в начале каждого часа.":"지금은 주변에 열린 균열이 없어요. 새 균열은 매시 정각에 열려요.",
"…и ещё {0} дальше":"…그리고 더 먼 곳에 {0}곳",
"Разломы открываются у Капищ каждый час. Подойди к Капищу на 100 м — или закрой Разлом издалека (до 5 км) по Дальнему пропуску.":"균열은 매시간 카피셰 곁에 열려요. 카피셰에 100m 안으로 다가가거나, 원거리 패스로 멀리서(최대 5km) 균열을 닫으세요.",
"Уклон":"회피",
"Тапай по экрану — атака.<br>Когда босс замахивается (!) — жми «Уклон» или смахни в сторону.":"화면을 탭하면 공격.<br>보스가 공격 자세(!)를 취하면 ‘회피’를 누르거나 옆으로 쓸어 넘기세요.",
"В бой!":"전투 시작!",
"За бой можно выпить не больше 3 флаконов":"한 전투에서 최대 3병까지 마실 수 있어요",
"Дух устал — выше не поднять, нужен отдых":"정령이 지쳤어요 — 더 올릴 수 없어요, 휴식이 필요해요",
"Дух и так полон сил":"정령의 체력이 이미 가득해요",
"Живой воды нет":"지바야 보다가 없어요",
"Уклон! −{0}":"회피! −{0}",
"Твои духи без сил.<br>Союзники ещё сражаются!":"내 정령이 모두 기절했어요.<br>동료들은 아직 싸우고 있어요!",
"Разлом закрыт!":"균열을 닫았어요!",
" (+{0} за скорость)":" (속도 보너스 +{0})",
" (+{0} за союзников)":" (동료 보너스 +{0})",
"Ослабленный {0} остался в нашем мире. У тебя <b>{1}</b> оберегов разлома{2}{3}.":"약해진 {0}이(가) 우리 세계에 남았어요. 균열 부적 <b>{1}</b>개{2}{3}.",
"Ловить!":"잡으러 가기!",
"Сервер не подтвердил этот бой. Проверь интернет и попробуй снова — разлом открыт до конца часа.":"서버가 이 전투를 확인하지 못했어요. 인터넷을 확인하고 다시 시도하세요. 균열은 이번 시간이 끝날 때까지 열려 있어요.",
"Разлом устоял":"균열이 버텨 냈어요",
"Осталось сил у босса: {0}%. Усиль духов, возьми стихию-противника и попробуй снова — разлом открыт до конца часа.":"보스의 남은 체력: {0}%. 정령을 강화하고 상성이 좋은 속성으로 다시 도전하세요. 균열은 이번 시간이 끝날 때까지 열려 있어요.",
"Покинуть битву?":"전투를 떠날까요?",
"Прогресс боя будет потерян.":"전투 진행 상황이 사라져요.",
