"Духи живут рядом с тобой":"정령은 가까이에 살아요",
"Игре нужна геопозиция, чтобы показать духов, родники и разломы вокруг. Прогресс хранится на сервере игры и доступен только тебе; сервер проверяет каждое действие (поэтому нужен интернет), в прогрессе есть дневник с местами поимок. Для проверки действий на карте сервер получает твоё местоположение. Чтобы загрузить места на карте и погоду, район (~1 км) запрашивается у OpenStreetMap и Open-Meteo (погоду можно выключить в настройках). Точные координаты уходят на сервер, только если ты сам предложишь новое место.":"주변의 정령, 샘, 균열을 보여 주려면 위치 정보가 필요해요. 진행 상황은 게임 서버에 저장되며 본인만 볼 수 있어요. 서버가 모든 행동을 확인하기 때문에 인터넷이 필요하고, 진행 상황에는 포획 장소가 담긴 일지가 있어요. 지도 위 행동을 확인하기 위해 서버가 내 위치를 받아요. 지도의 장소와 날씨를 불러오기 위해 대략적인 구역(~1km)을 OpenStreetMap과 Open-Meteo에 요청해요(날씨는 설정에서 끌 수 있어요). 정확한 좌표는 내가 새 장소를 제안할 때만 서버로 전송돼요.",
"Разрешить геопозицию":"위치 정보 허용",
"Уже играешь?":"이미 하고 있나요?",
"Войди — и твой прогресс откроется на этом устройстве":"로그인하면 이 기기에서 진행 상황을 이어갈 수 있어요",
"Назови себя":"이름을 입력하세요",
"Новое приложение":"새 앱",
"Игра переехала на свой сервер в России — <b>duholov.ru</b>. Для этого вышло новое приложение: его нужно установить заново.":"게임이 러시아의 자체 서버 <b>duholov.ru</b>로 이전했어요. 그래서 새 앱이 나왔고, 다시 설치해야 해요.",
"Привяжи вход: Меню → Настройки → Учётная запись (Google, Яндекс, VK, Telegram или почта). Без этого прогресс гостя не перенесётся.":"로그인을 연결하세요: 메뉴 → 설정 → 계정 (Google, 얀덱스, VK, Telegram 또는 이메일). 연결하지 않으면 게스트 진행 상황이 옮겨지지 않아요.",
"Удали это приложение.":"이 앱을 삭제하세요.",
"Скачай и установи новое — войди тем же способом.":"새 앱을 다운로드해 설치하고, 같은 방법으로 로그인하세요.",
